function Modal({ isOpen, onClose }) {
  const closeButtonRef = useRef(null);

  useEffect(() => {
    if (isOpen) {
      closeButtonRef.current?.focus();
    }
  }, [isOpen]);

  if (!isOpen) return null;

  return (
    <div role="dialog" aria-modal="true" aria-label="설정 모달">
      <button ref={closeButtonRef} onClick={onClose}>닫기</button>
      <div>모달 내용</div>
    </div>
  );
}

